#include "codegen/tac.h"
#include <ostream>
static int tempNo,labelNo; static std::ostream*out;
static std::string value(Node*n){if(n->kind=="literal"||n->kind=="id")return n->text;if(n->kind=="unary"){auto a=value(n->children[0]);std::string t="t"+std::to_string(++tempNo);*out<<t<<" = "<<n->text<<a<<'\n';return t;}if(n->kind=="binary"){auto a=value(n->children[0]),b=value(n->children[1]);std::string t="t"+std::to_string(++tempNo);*out<<t<<" = "<<a<<' '<<n->text<<' '<<b<<'\n';return t;}return "?";}
static void stmt(Node*n){if(!n)return;if(n->kind=="program"||n->kind=="block"){for(auto*c:n->children)stmt(c);return;}if(n->kind=="decl"){if(n->children.size()>1)*out<<n->children[0]->text<<" = "<<value(n->children[1])<<'\n';return;}if(n->kind=="assign"){*out<<n->text<<" = "<<value(n->children[0])<<'\n';return;}if(n->kind=="print"){*out<<"print "<<value(n->children[0])<<'\n';return;}if(n->kind=="if"){int id=++labelNo;auto c=value(n->children[0]);*out<<"ifFalse "<<c<<" goto L"<<id<<'\n';stmt(n->children[1]);if(n->children.size()>2){int end=++labelNo;*out<<"goto L"<<end<<"\nL"<<id<<":\n";stmt(n->children[2]);*out<<"L"<<end<<":\n";}else *out<<"L"<<id<<":\n";return;}if(n->kind=="while"){int top=++labelNo,done=++labelNo;*out<<"L"<<top<<":\n";auto c=value(n->children[0]);*out<<"ifFalse "<<c<<" goto L"<<done<<'\n';stmt(n->children[1]);*out<<"goto L"<<top<<"\nL"<<done<<":\n";}}
void generateTac(Node*r,std::ostream&o){tempNo=labelNo=0;out=&o;stmt(r);}
